chromeTest("Ch.2 section pages keep syllabus LOs at the top and DSE papers at the close", async () => {
  for (const page of ["26-1.html", "26-2.html", "26-3.html"]) {
    await cdp.goto(pageUrl(page));
    const info = await cdp.evaluate(`(function () {
      var blocks = Array.from(document.querySelectorAll(".lo-block"));
      var top = blocks[0];
      var close = document.querySelector(".lo-close");
      var scripts = Array.from(document.querySelectorAll("script[src]")).map(function (s) {
        return s.getAttribute("src") || "";
      });
      var papers = Array.from(document.querySelectorAll(".dse-paper"));
      var loaded = papers.filter(function (fig) {
        var img = fig.querySelector("img");
        return img && img.complete && img.naturalWidth > 0;
      }).length;
      return {
        nBlocks: blocks.length,
        heading: top && top.querySelector("h2") && top.querySelector("h2").textContent,
        stem: top && top.innerText,
        topChips: !!(top && top.querySelector(".dse-labels")),
        closeChips: close ? Array.from(close.querySelectorAll(".dse-labels a")).length : 0,
        nPapers: papers.length,
        loaded: loaded,
        remote: scripts.some(function (src) { return /^https?:\\/\\//.test(src); }),
        katexJs: scripts.some(function (src) { return /vendor\\/katex\\/katex\\.min\\.js$/.test(src); })
      };
    })()`);
    assert.equal(info.nBlocks, 2, "expected top and close LO blocks on " + page);
    assert.match(info.heading, /Learning objectives/i);
    assert.match(info.stem, /Students should be able to/);
    assert.equal(info.topChips, false, "top LO must not link questions on " + page);
    assert.ok(info.closeChips >= 1, "close LO should label DSE papers on " + page);
    assert.ok(info.nPapers >= 1, "expected section DSE embeds on " + page + ", n=" + info.nPapers);
    assert.ok(info.loaded >= 1, "localhost DSE images should load on " + page + ", loaded=" + info.loaded);
    assert.equal(info.remote, false, "no remote scripts on " + page);
    assert.equal(info.katexJs, true, "local KaTeX missing on " + page);
  }

  await cdp.goto(pageUrl("26-1.html"));
  const decay = await waitFor(async () => {
    const info = await cdp.evaluate(`(function () {
      var lo = document.querySelector(".lo-block");
      return {
        katex: !!document.querySelector(".katex"),
        exp: lo && lo.innerText,
        topChips: !!(lo && lo.querySelector(".dse-labels")),
        has2013: !!document.getElementById("dse-lq-2013-9")
      };
    })()`);
    if (!info.katex) throw new Error("katex not rendered");
    return info;
  }, 8000, "KaTeX on 26.1");
  assert.match(decay.exp, /exponential law of decay/);
  assert.match(decay.exp, /N\s*=\s*N/);
  assert.equal(decay.topChips, false);
  assert.equal(decay.has2013, true);

  await cdp.goto(pageUrl("summary.html"));
  const summary = await cdp.evaluate(`({
    lo: !!document.querySelector(".lo-block"),
    bank: !!document.querySelector(".dse-bank")
  })`);
  assert.equal(summary.lo, false, "summary should not dump chapter LOs");
  assert.equal(summary.bank, false, "summary should not dump chapter DSE papers");

  await cdp.goto(pageUrl("26-1.html"));
  await waitFor(async () => {
    const ok = await cdp.evaluate("!!document.querySelector('.lo-block .katex')");
    if (!ok) throw new Error("KaTeX missing in 26.1 LO");
    return true;
  }, 8000, "26.1 LO KaTeX");
  if (evidenceDir) {
    await cdp.screenshot(path.join(evidenceDir, "ch02-26-1-lo-katex.png"), ".lo-block");
  }

  await cdp.goto(pageUrl("26-2.html"));
  if (evidenceDir) {
    await cdp.evaluate(`(function () {
      var a = document.querySelector('.lo-close a[href="#dse-mc-2021-33"]');
      if (a && a.closest("li")) a.closest("li").scrollIntoView({ block: "center" });
    })()`);
    await cdp.evaluate("new Promise((r) => setTimeout(r, 180))");
    await cdp.screenshot(path.join(evidenceDir, "ch02-26-2-lo-2021-33-chip.png"));
  }
  await cdp.evaluate(`document.querySelector('.lo-close a[href="#dse-mc-2021-33"]').click()`);
  const land = await waitFor(async () => {
    const info = await cdp.evaluate(`(function () {
      var fig = document.getElementById("dse-mc-2021-33");
      var img = fig && fig.querySelector("img");
      var cap = fig && fig.querySelector("figcaption");
      return {
        href: location.href,
        hash: location.hash,
        caption: cap && cap.textContent,
        loaded: !!(img && img.complete && img.naturalWidth > 0)
      };
    })()`);
    if (!/#dse-mc-2021-33$/.test(info.href)) {
      throw new Error("wrong land href=" + info.href + " hash=" + info.hash);
    }
    if (!info.loaded) throw new Error("2021/33 image not loaded");
    return info;
  }, 10000, "26.2 chip to 2021/33");
  assert.equal(land.hash, "#dse-mc-2021-33");
  assert.match(land.caption || "", /2021\/33 MC/);
  assert.ok(land.loaded);
  if (evidenceDir) {
    await cdp.screenshot(path.join(evidenceDir, "ch02-26-2-chip-lands-on-2021-33.png"), "#dse-mc-2021-33");
  }

  await cdp.goto(ch1Url("25-2.html"));
  const ch1 = await waitFor(async () => {
    const info = await cdp.evaluate(`(function () {
      var fig = document.getElementById("dse-mc-2021-33");
      var img = fig && fig.querySelector("img");
      return {
        src: img && img.getAttribute("src"),
        loaded: !!(img && img.complete && img.naturalWidth > 0),
        caption: fig && fig.querySelector("figcaption") && fig.querySelector("figcaption").textContent
      };
    })()`);
    if (!info.loaded) throw new Error("Ch.1 2021/33 not loaded");
    return info;
  }, 8000, "Ch.1 25.2 still embeds 2021/33");
  assert.match(ch1.src || "", /mc\/25\/2021_q33\.png$/);
  assert.match(ch1.caption || "", /2021\/33 MC/);
  if (evidenceDir) {
    await cdp.screenshot(path.join(evidenceDir, "ch01-25-2-dse-mc-2021-33.png"), "#dse-mc-2021-33");
  }
});
